INSERT INTO tmp_om_im9b (t_id, t_cat, t_rar, t_har, t_desc) VALUES
  (1188, 33, 5, 1, '<p>Chaque anneau de maîtrise élémentaire est lié à l’un des quatre Plans Élémentaires. Le MJ choisit ou laisse le hasard décider à quel plan il est lié. Par exemple, un anneau de maîtrise élémentaire (air) est lié au Plan Élémentaire de l’Air.</p><p>Chaque anneau de maîtrise élémentaire est doté des deux propriétés suivantes :</p><p><b>Fléau élémentaire.</b> Tant que vous portez cet anneau, vous avez l’Avantage aux jets d’attaque contre les Élémentaires originaires du plan lié, qui subissent le Désavantage à leurs jets d’attaque contre vous.</p><p><b>Coercition élémentaire.</b> Tant que vous portez l’anneau, vous pouvez entreprendre l’action Magie pour tenter de contraindre un Élémentaire que vous voyez dans un rayon de 18 m. L’Élémentaire effectue un jet de sauvegarde de Sagesse DD 18. En cas d’échec, il subit l’état Charmé jusqu’au début de votre tour suivant, et vous déterminez comment il consacre son déplacement et son action à son tour suivant.</p><p><b>Affinité élémentaire.</b> Tant que vous portez l’anneau, vous bénéficiez de propriétés supplémentaires correspondant au Plan Élémentaire qui y est lié :</p><p><b>Sorts.</b> L’anneau dispose de 5 charges et récupère quotidiennement 1d4 + 1 charges dépensées, à l’aube. Tant que vous portez l’anneau, vous pouvez lancer un sort par son intermédiaire. Choisissez le sort dans la liste des sorts disponibles, comme indiqué dans la table suivante (selon le Plan Élémentaire auquel l’anneau est lié). La table indique le nombre de charges à dépenser pour lancer le sort, dont le DD de sauvegarde est de 18.</p><p><b>Air.</b> Vous parlez l’aérien, bénéficiez de la Résistance aux dégâts de foudre, ainsi que d’une Vitesse de vol égale à votre Vitesse (avec le vol stationnaire).</p>'),
  (1189, 33, 5, 1, '<p>Chaque anneau de maîtrise élémentaire est lié à l’un des quatre Plans Élémentaires. Le MJ choisit ou laisse le hasard décider à quel plan il est lié. Par exemple, un anneau de maîtrise élémentaire (air) est lié au Plan Élémentaire de l’Air.</p><p>Chaque anneau de maîtrise élémentaire est doté des deux propriétés suivantes :</p><p><b>Fléau élémentaire.</b> Tant que vous portez cet anneau, vous avez l’Avantage aux jets d’attaque contre les Élémentaires originaires du plan lié, qui subissent le Désavantage à leurs jets d’attaque contre vous.</p><p><b>Coercition élémentaire.</b> Tant que vous portez l’anneau, vous pouvez entreprendre l’action Magie pour tenter de contraindre un Élémentaire que vous voyez dans un rayon de 18 m. L’Élémentaire effectue un jet de sauvegarde de Sagesse DD 18. En cas d’échec, il subit l’état Charmé jusqu’au début de votre tour suivant, et vous déterminez comment il consacre son déplacement et son action à son tour suivant.</p><p><b>Affinité élémentaire.</b> Tant que vous portez l’anneau, vous bénéficiez de propriétés supplémentaires correspondant au Plan Élémentaire qui y est lié :</p><p><b>Sorts.</b> L’anneau dispose de 5 charges et récupère quotidiennement 1d4 + 1 charges dépensées, à l’aube. Tant que vous portez l’anneau, vous pouvez lancer un sort par son intermédiaire. Choisissez le sort dans la liste des sorts disponibles, comme indiqué dans la table suivante (selon le Plan Élémentaire auquel l’anneau est lié). La table indique le nombre de charges à dépenser pour lancer le sort, dont le DD de sauvegarde est de 18.</p><p><b>Eau.</b> Vous parlez l’aquatique, recevez une Vitesse de nage de 18 m et pouvez respirer sous l’eau.</p>'),
  (1190, 33, 5, 1, '<p>Chaque anneau de maîtrise élémentaire est lié à l’un des quatre Plans Élémentaires. Le MJ choisit ou laisse le hasard décider à quel plan il est lié. Par exemple, un anneau de maîtrise élémentaire (air) est lié au Plan Élémentaire de l’Air.</p><p>Chaque anneau de maîtrise élémentaire est doté des deux propriétés suivantes :</p><p><b>Fléau élémentaire.</b> Tant que vous portez cet anneau, vous avez l’Avantage aux jets d’attaque contre les Élémentaires originaires du plan lié, qui subissent le Désavantage à leurs jets d’attaque contre vous.</p><p><b>Coercition élémentaire.</b> Tant que vous portez l’anneau, vous pouvez entreprendre l’action Magie pour tenter de contraindre un Élémentaire que vous voyez dans un rayon de 18 m. L’Élémentaire effectue un jet de sauvegarde de Sagesse DD 18. En cas d’échec, il subit l’état Charmé jusqu’au début de votre tour suivant, et vous déterminez comment il consacre son déplacement et son action à son tour suivant.</p><p><b>Affinité élémentaire.</b> Tant que vous portez l’anneau, vous bénéficiez de propriétés supplémentaires correspondant au Plan Élémentaire qui y est lié :</p><p><b>Sorts.</b> L’anneau dispose de 5 charges et récupère quotidiennement 1d4 + 1 charges dépensées, à l’aube. Tant que vous portez l’anneau, vous pouvez lancer un sort par son intermédiaire. Choisissez le sort dans la liste des sorts disponibles, comme indiqué dans la table suivante (selon le Plan Élémentaire auquel l’anneau est lié). La table indique le nombre de charges à dépenser pour lancer le sort, dont le DD de sauvegarde est de 18.</p><p><b>Feu.</b> Vous parlez l’igné et bénéficiez de l’Immunité contre les dégâts de feu.</p>'),
  (1191, 33, 5, 1, '<p>Chaque anneau de maîtrise élémentaire est lié à l’un des quatre Plans Élémentaires. Le MJ choisit ou laisse le hasard décider à quel plan il est lié. Par exemple, un anneau de maîtrise élémentaire (air) est lié au Plan Élémentaire de l’Air.</p><p>Chaque anneau de maîtrise élémentaire est doté des deux propriétés suivantes :</p><p><b>Fléau élémentaire.</b> Tant que vous portez cet anneau, vous avez l’Avantage aux jets d’attaque contre les Élémentaires originaires du plan lié, qui subissent le Désavantage à leurs jets d’attaque contre vous.</p><p><b>Coercition élémentaire.</b> Tant que vous portez l’anneau, vous pouvez entreprendre l’action Magie pour tenter de contraindre un Élémentaire que vous voyez dans un rayon de 18 m. L’Élémentaire effectue un jet de sauvegarde de Sagesse DD 18. En cas d’échec, il subit l’état Charmé jusqu’au début de votre tour suivant, et vous déterminez comment il consacre son déplacement et son action à son tour suivant.</p><p><b>Affinité élémentaire.</b> Tant que vous portez l’anneau, vous bénéficiez de propriétés supplémentaires correspondant au Plan Élémentaire qui y est lié :</p><p><b>Sorts.</b> L’anneau dispose de 5 charges et récupère quotidiennement 1d4 + 1 charges dépensées, à l’aube. Tant que vous portez l’anneau, vous pouvez lancer un sort par son intermédiaire. Choisissez le sort dans la liste des sorts disponibles, comme indiqué dans la table suivante (selon le Plan Élémentaire auquel l’anneau est lié). La table indique le nombre de charges à dépenser pour lancer le sort, dont le DD de sauvegarde est de 18.</p><p><b>Terre.</b> Vous parlez le terreux et bénéficiez de la Résistance aux dégâts d’acide. Les sols composés ou jonchés de gravats, de roches ou de terre ne constituent pas un Terrain difficile pour vous. Vous pouvez en outre traverser la terre ou la roche solide comme s’il s’agissait d’un simple Terrain difficile, sans même perturber la matière traversée. Si vous terminez votre tour dans la terre ou la roche solide, vous êtes expulsé vers l’espace inoccupé le plus proche parmi ceux que vous venez d’occuper.</p>'),
  (1198, 33, 3, 0, '<p>Tant que vous portez cet anneau, vous bénéficiez de la Résistance à un type de dégâts. La gemme de l’anneau indique le type, que le MJ choisit ou détermine aléatoirement selon la table suivante.</p>'),
  (1199, 33, 3, 0, '<p>Tant que vous portez cet anneau, vous bénéficiez de la Résistance à un type de dégâts. La gemme de l’anneau indique le type, que le MJ choisit ou détermine aléatoirement selon la table suivante.</p>'),
