  (1207, 33, 3, 0, '<p>Tant que vous portez cet anneau, vous bénéficiez de la Résistance à un type de dégâts. La gemme de l’anneau indique le type, que le MJ choisit ou détermine aléatoirement selon la table suivante.</p>'),
  (1215, 34, 2, 0, '<p>Vous recevez un bonus aux jets d’attaque et de dégâts effectués avec cette arme magique. Ce bonus est déterminé par la rareté de l’arme.</p>'),
  (1216, 34, 3, 0, '<p>Vous recevez un bonus aux jets d’attaque et de dégâts effectués avec cette arme magique. Ce bonus est déterminé par la rareté de l’arme.</p>'),
  (1217, 34, 4, 0, '<p>Vous recevez un bonus aux jets d’attaque et de dégâts effectués avec cette arme magique. Ce bonus est déterminé par la rareté de l’arme.</p>'),
  (1251, 35, 3, 0, '<p>Vous recevez un bonus à la CA tant que vous portez cette armure. Ce bonus est déterminé par sa rareté.</p>'),
  (1252, 35, 4, 0, '<p>Vous recevez un bonus à la CA tant que vous portez cette armure. Ce bonus est déterminé par sa rareté.</p>'),
