-- sql/2026-08-28_objets_dd2024_sp-im9b.sql
-- SP-IM9b — Les déclinaisons d'entrées génériques du SRD (objets magiques DD2024).
--
-- Source : FR_SRD_CC_v5.2.1-objets_magiques.pdf.
-- Arbitrage du 2026-08-28 (D-IM16) : les déclinaisons sont CONSERVÉES.
--
-- Le script d'import antérieur avait éclaté 20 entrées génériques du SRD en
-- déclinaisons : « Anneau de résistance » et sa table de types de dégâts est
-- devenue 10 lignes, la Pierre de Ioun 14, la Figurine merveilleuse 11…
-- C'est le bon modèle pour le jeu — un inventaire doit pouvoir désigner
-- « Anneau de résistance (feu) » — mais ces lignes ne se rapprochent d'aucune
-- entrée du PDF par leur nom : SP-IM9a les avait donc laissées de côté.
--
-- Ce patch leur donne :
--   * le TEXTE de leur générique, table exclue. Pour une déclinaison, le contenu
--     de la table du SRD est précisément ce que porte om_rarete : le reproduire
--     dans la description n'aurait aucun intérêt.
--   * leur RARETÉ PROPRE, lue dans cette même table. Exemples : « Arme +2 »
--     est rare quand « Arme +1 » est peu courante ; « Cor du Valhalla (fer) »
--     est légendaire quand celui d'argent est rare ; « Pierre de Ioun —
--     Protection » est rare quand celle de Maîtrise est légendaire.
--   * la catégorie et l'harmonisation du générique.
--
-- Pour les trois familles dont le SRD décrit chaque variante dans son propre
-- paragraphe — Pierre de Ioun, Plume magique, Figurine merveilleuse — la
-- description reprend le chapeau du générique PUIS le paragraphe de la variante
-- seule. « Pierre de Ioun — Agilité » décrit l'agilité, pas les quatorze pierres.
--
-- « Armure de cuir clouté enchantée » est traitée à part : sa ligne de type dans
-- le PDF est « Armure (armure de cuir clouté) rare », SANS virgule avant la
-- rareté. Le parseur ne la reconnaissait pas et l'objet était resté sans rareté.
--
-- IDEMPOTENCE : UPDATE ciblés par om_id via une table temporaire. Rejouable.

-- ------------------------------------------------------------
-- Redressement de 121 déclinaisons
-- ------------------------------------------------------------

DROP TEMPORARY TABLE IF EXISTS tmp_om_im9b;

CREATE TEMPORARY TABLE tmp_om_im9b (
  t_id   INT UNSIGNED NOT NULL PRIMARY KEY,
  t_cat  INT UNSIGNED NOT NULL,
  t_rar  TINYINT      NOT NULL,
  t_har  TINYINT      NOT NULL,
  t_desc TEXT         NOT NULL
) ENGINE=InnoDB;


UPDATE dd_objets_magiques o
  JOIN tmp_om_im9b t ON t.t_id = o.om_id
SET o.om_com_id        = t.t_cat,
    o.om_rarete        = t.t_rar,
    o.om_harmonisation = t.t_har,
    o.om_description   = t.t_desc;

DROP TEMPORARY TABLE tmp_om_im9b;
